llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Ipratropium, a quaternary ammonium anticholinergic with a cationic bicyclic core and polar hydroxyl/ester groups, had absolute oral bioavailability of 2.0% in healthy volunteers, directly supporting low F for the similarly quaternary ammonium query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Physostigmine, a fused N-methyl indole alkaloid with carbamate and multiple polar groups, had absolute oral bioavailability of 3% as an oral solution, supporting low F due to extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Nitrendipine, despite near-complete gastrointestinal absorption, had absolute oral bioavailability of 10.7% in humans due to first-pass metabolism and efflux, supporting low F for a molecule with substantial clearance liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Pentazocine had mean oral bioavailability of 18% in patients, below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Oxybutynin (R-enantiomer) had estimated oral bioavailability of about 6.7% in a pharmacokinetic model, supporting low F for a molecule with ester and basic amine functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Lisuride had oral bioavailability of 10% at 100 µg in humans, supporting low F despite some dose-dependent higher values at larger doses.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "One ipratropium study reported about 32% oral bioavailability at a 30 mg dose, which would be above the 20% threshold, but this is inconsistent with multiple other ipratropium absolute bioavailability studies reporting 2-3% and is treated as an outlier.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary ammonium polycyclic alkaloid; the closest high-transfer analogue ipratropium has absolute oral bioavailability of 2-3% in humans, and multiple other transferable analogues (physostigmine, nitrendipine, pentazocine, oxybutynin, lisuride) show F below or near the 20% threshold. The weight of experimental evidence predicts low oral bioavailability (<20%).",
  "evidence_gaps": [
    "No direct human absolute bioavailability study for the query molecule itself.",
    "One ipratropium record (C41) reported ~32% F at 30 mg, inconsistent with other ipratropium studies; unresolved outlier.",
    "Some lisuride and physostigmine records show dose-dependent values above 20%, adding minor uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

